import{_ as o,o as t,c as d,ag as a}from"./chunks/framework.BaNuf0sO.js";const h=JSON.parse('{"title":"page-layout（页面布局族）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/core/src/components/page-layout/README.md","filePath":"docs/core/src/components/page-layout/README.md"}'),c={name:"docs/core/src/components/page-layout/README.md"};function p(l,e,r,s,i,n){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="page-layout-页面布局族" tabindex="-1">page-layout（页面布局族） <a class="header-anchor" href="#page-layout-页面布局族" aria-label="Permalink to &quot;page-layout（页面布局族）&quot;">​</a></h1><blockquote><p><strong>准入标准：组件的 DOM 根节点是 <code>AppPage</code></strong>（默认形态下）。想进本族的组件 [MUST] 满足它。 例外只有显式的 <code>embedded</code> 开关（<code>AppPageDetail</code> / <code>AppPageListDetailLayout</code>）：开了即不渲染 <code>AppPage</code>、作为组件嵌进宿主页面。 标准由 <code>__tests__/family-contract.test.ts</code> 守卫（逐个挂载断言根元素带 <code>.app-page</code>， 并校验族内每个 <code>.vue</code> 都在清单里，防漏登记绕过）。</p></blockquote><h2 id="这个族是什么" tabindex="-1">这个族是什么 <a class="header-anchor" href="#这个族是什么" aria-label="Permalink to &quot;这个族是什么&quot;">​</a></h2><p>「<strong>一整页</strong>」级别的编排组件：使用方把它当路由页的根来用，页面的四向 chrome、内容视口几何、 弹层挂载点等由它内含的 <code>AppPage</code> 统一提供。故本族组件与 <code>AppPage</code> 是<strong>二选一</strong>关系 ——[MUST NOT] 出现「业务写 <code>AppPage</code> 再套本族组件」的嵌套。</p><p><strong><code>AppPage</code> 自己不在本族</strong>：它是<strong>被</strong>本族使用的页面原语（留在 <code>app-layout</code>，与 <code>AppLayout</code> / <code>AppBody</code> 同族）。本族是「用 AppPage 搭出来的成品页型」。</p><h2 id="组件清单" tabindex="-1">组件清单 <a class="header-anchor" href="#组件清单" aria-label="Permalink to &quot;组件清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>对外</th><th>一句话</th></tr></thead><tbody><tr><td><code>AppPageListDetailLayout</code></td><td>✅</td><td>列表 / 详情同页范式（master-detail）门面：一根 <code>activeId</code> 状态线打通列表与详情，宽屏并排 / 窄屏叠加两形态按视口宽定档</td></tr><tr><td><code>AppPageDetail</code></td><td>✅</td><td>详情区。默认自带 <code>AppPage</code>、可<strong>独立成详情页</strong>；<code>embedded</code> 开启后走透传态供门面内嵌</td></tr><tr><td><code>AppPageListDetailSplit</code></td><td>✗</td><td>宽屏并排形态（门面实现细节）</td></tr><tr><td><code>AppPageListDetailSheet</code></td><td>✗</td><td>窄屏叠加形态（抽屉 / 弹窗，门面实现细节）</td></tr></tbody></table><p>两个形态件与 <code>use-list-detail.ts</code> [MUST NOT] 出桶——换承载体不算 breaking。</p><h2 id="详情区底边-detailbottom-与页面底边-bottom" tabindex="-1">详情区底边（<code>#detailBottom</code>）与页面底边（<code>#bottom</code>） <a class="header-anchor" href="#详情区底边-detailbottom-与页面底边-bottom" aria-label="Permalink to &quot;详情区底边（`#detailBottom`）与页面底边（`#bottom`）&quot;">​</a></h2><p>门面上<strong>两个都有、同名不同物</strong>，[MUST] 分清：</p><ul><li><code>#bottom</code> → <code>AppPage</code> 的<strong>页面级四向悬浮槽</strong>，覆盖整页底边（列表 + 详情都在它上方）；</li><li><code>#detailBottom</code> → 逐层透到内置 <code>ViewLayout</code> 的 <code>#bottom</code>，只是<strong>详情区内部</strong>的底边 （split 档钉在详情区底 / sheet 档钉在抽屉底），scope 与 <code>#detail</code> 完全一致。</li></ul><p>判据：<strong>对「当前这一条」的操作放 <code>#detailBottom</code>，对整页的放 <code>#bottom</code>。</strong> 用了 <code>#detailBottom</code> 即自动开 <code>ViewLayout.fillHeight</code>（内容盒定高 ⇒ 底边贴容器底）； 没用则一个字都不传，其余 refine 页面零波及。 透传链四层：<code>AppPageListDetailLayout</code> → <code>Split</code> / <code>Sheet</code> → <code>AppPageDetail</code> → <code>ViewLayout#bottom</code>， 每层 <code>v-if=&quot;$slots.detailBottom&quot;</code> 守着 —— 不传即零渲染，[MUST NOT] 无条件透一个空槽下去 （精细流下空盒会被量高计入 reserve）。</p><h2 id="标准的唯一例外" tabindex="-1">标准的唯一例外 <a class="header-anchor" href="#标准的唯一例外" aria-label="Permalink to &quot;标准的唯一例外&quot;">​</a></h2><p><code>AppPageDetail</code> 的 <strong><code>embedded=true</code></strong> 是<strong>显式 opt-out</strong>：宿主（Split / Sheet）已经有一层 <code>AppPage</code>，再套就成两层，故内嵌态走 <code>SlotLayoutTemplate</code> 透传、不产生宿主元素。 守卫测试单独锁住了这条语义（开了就不该有 <code>.app-page</code>）。</p><p>⚠️ 用 <code>SlotLayoutTemplate :disabled</code> 做透传是<strong>有前提</strong>的：它的透传态只渲染默认槽、 <strong>具名槽无落点</strong>。<code>AppPageDetail</code> 只用 <code>AppPage</code> 的默认槽，故成立；两个形态件要用 <code>#left</code> / <code>#right</code> 等具名槽，[MUST NOT] 照抄。</p><h2 id="文档" tabindex="-1">文档 <a class="header-anchor" href="#文档" aria-label="Permalink to &quot;文档&quot;">​</a></h2><ul><li><a href="/done-coding-showcase/docs/core/src/components/page-layout/docs/README-AppPageListDetailLayout.html">README-AppPageListDetailLayout.md</a></li><li><a href="/done-coding-showcase/docs/core/src/components/page-layout/docs/README-AppPageDetail.html">README-AppPageDetail.md</a></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>页面原语：<code>AppPage</code>（app-layout 族）</li><li>不变式内核：<code>hooks/use-active-record.ts</code></li><li>上下文 key：<code>APP_PAGE_LIST_DETAIL_CONTEXT</code></li><li>spec：<code>docs/specs/2026-08-31-025041-moderate-列表详情同页范式AppPageListDetailLayout/spec.md</code></li></ul>',19)])])}const u=o(c,[["render",p]]);export{h as __pageData,u as default};
